import type { LinkButtonProps } from "./link-button.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { PolymorphicRef } from "src/types/component";

import { LinkButtonClasses, StyledLinkButton } from "./link-button.styles";

const LinkButton = forwardRef(function LinkButton<C extends React.ElementType = "button">(
  { as, className, variant = "default", children, disabled, size, ...props }: LinkButtonProps<C>,
  ref: PolymorphicRef,
) {
  const theme = useTheme();
  const rootClasses = clsx(LinkButtonClasses.root, className, {
    [LinkButtonClasses.sm]: size === "sm",
  });

  const handleClick = (e: React.MouseEvent) => {
    if (disabled) {
      e.preventDefault();
      return;
    }
    if (props.onClick) {
      props.onClick(e);
    }
  };

  const inferredAs = as || ("href" in props ? "a" : "button");

  return (
    <StyledLinkButton
      ref={ref}
      aria-disabled={disabled}
      as={inferredAs}
      className={rootClasses}
      currentTheme={theme}
      data-disabled={disabled}
      disabled={disabled}
      variant={variant}
      {...props}
      onClick={handleClick}
    >
      {children}
    </StyledLinkButton>
  );
});

LinkButton.displayName = "LinkButton";

export default LinkButton;
